-- Staging only; all synthetic identities, mappings, reply intents and audit evidence roll back.
begin;
do $$
declare u uuid;a uuid;b uuid;old_role uuid;scoped uuid:=gen_random_uuid();ctx jsonb;basis jsonb;r jsonb;lease jsonb;
 id1 uuid:=gen_random_uuid();id2 uuid:=gen_random_uuid();sealed jsonb:='{"fixture":"old"}';new_sealed jsonb:='{"fixture":"new"}';
 review text:='accounts/replyfixture/locations/fixture/reviews/fixture';expires timestamptz;n integer;
begin
 select id into a from public.outlets where name='QA Demo — Reporting Posters';select id into b from public.outlets where name='Friends Corner';
 select e.auth_user_id,e.role_id into u,old_role from public.employees e join public.roles ro on ro.id=e.role_id where lower(ro.name)='owner' and e.enable_system_login and e.access_state='active' and e.auth_user_id is not null limit 1;
 if u is null or a is null or b is null then raise exception 'Staging rollback fixtures unavailable.';end if;
 assert not has_function_privilege('anon','public.crew_google_business_reply_server(text,uuid,uuid,jsonb)','EXECUTE');
 assert not has_function_privilege('authenticated','public.crew_google_business_reply_server(text,uuid,uuid,jsonb)','EXECUTE');
 assert has_function_privilege('service_role','public.crew_google_business_reply_server(text,uuid,uuid,jsonb)','EXECUTE');
 assert not has_table_privilege('authenticated','google_business_private.reply_requests','SELECT');
 ctx:=public.crew_google_business_server('context',u,a);
 assert ctx->>'connection_status'='connected';
 insert into public.crew_google_business_locations(resource_name,account_resource_name,display_name) values('accounts/replyfixture/locations/fixture','accounts/replyfixture','Rollback reply fixture');
 perform public.crew_google_business_server('map',u,a,jsonb_build_object('location','accounts/replyfixture/locations/fixture','generation',ctx->'generation','expected_revision',ctx->'mapping'->>'revision'));
 ctx:=public.crew_google_business_server('context',u,a);basis:=jsonb_build_object('review',review,'generation',ctx->'generation','revision',ctx->'mapping'->>'revision','confirmed',true,'operation','publish','payload_hash',repeat('a',64),'desired_hash',repeat('b',64),'sealed_intent',sealed);
 assert (public.crew_google_business_reply_server('access',u,a,jsonb_build_object('review',review)))->>'can_reply'='true';
 begin perform public.crew_google_business_reply_server('access',u,b,jsonb_build_object('review',review));raise exception 'Foreign mapping allowed';exception when raise_exception then assert sqlerrm='Review does not belong to this outlet mapping.';end;
 perform public.crew_google_business_reply_server('prepare',u,a,basis||jsonb_build_object('id',id1));
 perform public.crew_google_business_reply_server('prepare',u,a,basis||jsonb_build_object('id',id1));
 assert (select count(*)=1 from google_business_private.reply_requests where id=id1);
 begin perform public.crew_google_business_reply_server('prepare',u,a,basis||jsonb_build_object('id',id1,'payload_hash',repeat('c',64)));raise exception 'ID reused for changed intent';exception when raise_exception then assert sqlerrm='Reply request ID was already used for a different intent.';end;
 r:=public.crew_google_business_reply_server('claim',u,a,jsonb_build_object('id',id1));assert r->>'claimed'='true';
 assert (public.crew_google_business_reply_guard(u,a,id1,(r->>'lease')::uuid))->>'ok'='true';
 begin perform public.crew_google_business_reply_guard(u,a,id1,gen_random_uuid());raise exception 'Wrong lease allowed';exception when raise_exception then assert sqlerrm='Reply authority changed. Check status before retrying.';end;
 assert (public.crew_google_business_reply_server('claim',u,a,jsonb_build_object('id',id1)))->>'claimed'='false';
 perform public.crew_google_business_reply_server('prepare',u,a,basis||jsonb_build_object('id',id2));
 begin perform public.crew_google_business_reply_server('claim',u,a,jsonb_build_object('id',id2));raise exception 'Concurrent intent allowed';exception when raise_exception then assert sqlerrm='Another reply update is unresolved. Check its status in Reply History.';end;
 perform public.crew_google_business_reply_server('finish',u,a,jsonb_build_object('id',id1,'lease',r->>'lease','status','uncertain','code','reply_outcome_uncertain'));
 r:=public.crew_google_business_reply_server('check',u,a,jsonb_build_object('id',id1));assert r->>'read_only'='true';
 lease:=public.crew_google_business_server('sync_begin',u,a,jsonb_build_object('generation',ctx->'generation','revision',ctx->'mapping'->>'revision'));
 perform public.crew_google_business_server('sync_finish',u,a,jsonb_build_object('generation',ctx->'generation','revision',ctx->'mapping'->>'revision','lease',lease->>'lease','sealed_reviews',sealed));
 select expires_at into expires from google_business_private.inbox_cache where location_resource_name='accounts/replyfixture/locations/fixture';
 perform public.crew_google_business_reply_server('finish',u,a,jsonb_build_object('id',id1,'lease',r->>'lease','status','confirmed','code','remote_reply_reconciled','sealed_remote',new_sealed,'remote_hash',repeat('b',64),'remote_time',now(),'expected_cache',sealed,'sealed_projection',new_sealed));
 assert (select sealed_reviews=new_sealed and expires_at=expires from google_business_private.inbox_cache where location_resource_name='accounts/replyfixture/locations/fixture');
 select count(*) into n from google_business_private.events where action='reply_outcome' and details->>'request_id'=id1::text;
 perform public.crew_google_business_reply_server('finish',u,a,jsonb_build_object('id',id1,'lease',r->>'lease','status','confirmed'));
 assert (select count(*)=n from google_business_private.events where action='reply_outcome' and details->>'request_id'=id1::text);
 assert (public.crew_google_business_reply_server('claim',u,a,jsonb_build_object('id',id1)))->>'claimed'='false';
 -- Selected-outlet reviewer can reply without gaining shared connection/mapping management.
 insert into public.roles(id,name,outlet_access_type) values(scoped,'QA owner reply rollback reviewer','selected');
 insert into public.role_permissions(role_id,permission_id) select scoped,id from public.permissions where code in ('crew_performance.view','crew_performance.review');
 insert into public.role_outlets(role_id,outlet_id) values(scoped,a);update public.employees set role_id=scoped where auth_user_id=u;
 assert google_business_private.reply_allowed(u,a);assert not google_business_private.allowed(u,a,true);
 begin perform public.crew_google_business_reply_server('access',u,b,jsonb_build_object('review',review));raise exception 'Outlet scope escaped';exception when insufficient_privilege then null;end;
 r:=public.crew_google_business_reply_server('claim',u,a,jsonb_build_object('id',id2));
 delete from public.role_permissions where role_id=scoped and permission_id in(select id from public.permissions where code='crew_performance.review');
 assert not google_business_private.reply_allowed(u,a);
 begin perform public.crew_google_business_reply_guard(u,a,id2,(r->>'lease')::uuid);raise exception 'Revoked reply permission allowed';exception when insufficient_privilege then null;end;
 perform public.crew_google_business_reply_server('finish',u,a,jsonb_build_object('id',id2,'lease',r->>'lease','status','rejected','code','reply_authority_changed'));
 begin perform public.crew_google_business_reply_server('prepare',u,a,basis||jsonb_build_object('id',gen_random_uuid()));raise exception 'Reader published reply';exception when insufficient_privilege then null;end;
 update public.employees set role_id=old_role where auth_user_id=u;
 update google_business_private.reply_requests set content_expires_at=now()-interval '1 second' where id=id1;
 perform google_business_private.purge_reply_content();assert (select sealed_intent is null and sealed_remote is null and status='confirmed' from google_business_private.reply_requests where id=id1);
 assert exists(select 1 from google_business_private.events where action='reply_outcome' and details->>'request_id'=id1::text and details->>'remote_hash'=repeat('b',64));
end;$$;
rollback;
